use std::path::PathBuf;

/// Output sample rate of speech generated by LFM3 Omni (verified on the installed files).
pub const SPEECH_SAMPLE_RATE: u32 = 24_000;

/// The two model roles the app runs. Serialized IDs stay `small` / `omni`.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum ModelRole {
    Small,
    Omni,
}

/// Requested device. `Auto` tries every GPU backend the build includes and the machine can open (CUDA, then
/// Metal), and falls back to the CPU when none opens or a GPU load fails.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum DevicePreference {
    #[default]
    Auto,
    Cpu,
    Metal,
    Cuda,
}

impl DevicePreference {
    /// Parses `auto`, `cpu`, `cuda` or `metal`, ignoring case and surrounding spaces.
    pub fn parse(value: &str) -> Option<Self> {
        match value.trim().to_ascii_lowercase().as_str() {
            "auto" | "" => Some(Self::Auto),
            "cpu" => Some(Self::Cpu),
            "cuda" | "gpu" => Some(Self::Cuda),
            "metal" => Some(Self::Metal),
            _ => None,
        }
    }
}

/// The device a model actually runs on.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Default)]
pub enum ComputeDevice {
    #[default]
    Cpu,
    Cuda,
    Metal,
}

impl ComputeDevice {
    pub fn as_str(self) -> &'static str {
        match self {
            Self::Cpu => "cpu",
            Self::Cuda => "cuda",
            Self::Metal => "metal",
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct LoadSpec {
    pub role: ModelRole,
    pub weights: PathBuf,
    pub projector: Option<PathBuf>,
    /// Maximum prompt plus output tokens the engine plans memory for.
    pub context_tokens: usize,
    /// Maximum generations that may run at the same time for this model.
    pub max_concurrent: usize,
    pub device: DevicePreference,
}

/// What a loaded model can actually do. Reported truthfully; never inferred
/// from settings.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub struct Capabilities {
    pub text: bool,
    pub vision: bool,
    pub asr: bool,
    pub tts: bool,
    /// Speech arrives as chunks while it is generated.
    pub voice_streaming: bool,
    /// Full-duplex realtime audio (listen while speaking). Not implemented by the engine.
    pub realtime_full_duplex: bool,
    /// Selecting a named or gendered speaker. The engine has no voice selector.
    pub voice_selection: bool,
    /// Cloning a speaker from a reference clip. The engine ignores references.
    pub speaker_reference: bool,
}

/// One chat message. Images are encoded files (PNG, JPEG, WebP, GIF, BMP) and
/// audio is WAV bytes. Both are decoded by the engine adapter.
#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub struct ChatMessage {
    pub role: String,
    pub content: String,
    pub images: Vec<Vec<u8>>,
    pub audio_wav: Vec<Vec<u8>>,
}

impl ChatMessage {
    /// A text-only message.
    pub fn text(role: impl Into<String>, content: impl Into<String>) -> Self {
        Self {
            role: role.into(),
            content: content.into(),
            ..Self::default()
        }
    }
}

#[derive(Debug, Clone, PartialEq)]
pub struct ChatRequest {
    pub messages: Vec<ChatMessage>,
    pub max_output_tokens: u32,
    pub temperature: f32,
    /// Strings that end generation. They are not part of the output.
    pub stop: Vec<String>,
    /// Whether the model may spend tokens on hidden reasoning.
    pub enable_thinking: bool,
    /// Also produce spoken audio (`AudioChunk` events, PCM16 at `SPEECH_SAMPLE_RATE`).
    /// Only Omni models with a projector support this.
    pub speech: bool,
}

impl ChatRequest {
    /// A request with the app's defaults: no thinking, no speech, no stop strings.
    pub fn new(messages: Vec<ChatMessage>, max_output_tokens: u32) -> Self {
        Self {
            messages,
            max_output_tokens,
            temperature: 0.0,
            stop: Vec::new(),
            enable_thinking: false,
            speech: false,
        }
    }
}

/// Stable events produced by any engine.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum InferenceEvent {
    TextDelta(String),
    ReasoningDelta(String),
    ToolCallDelta(String),
    AudioChunk {
        pcm16: Vec<u8>,
        sample_rate: u32,
    },
    Usage {
        prompt_tokens: u64,
        output_tokens: u64,
    },
    Finished,
}

/// Lifecycle state of one model role.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ModelState {
    Unloaded,
    Loading,
    Ready,
    Busy,
    Unloading,
    Failed(String),
}
